WITH filtered_departments AS (SELECT * FROM departments WHERE location IN ('Singapore', 'Tokyo') AND location = 'Singapore'), summary AS (SELECT CASE WHEN budget >= 3674000 THEN 'high' WHEN budget >= 988000 THEN 'mid' ELSE 'low' END AS budget_bucket, CASE WHEN location IN ('Berlin', 'Chiang Mai') THEN 'tier_1' ELSE 'other' END AS location_group, SUM(CASE WHEN dept_name = 'Engineering' THEN 1 ELSE 0 END) AS engineering_count FROM filtered_departments GROUP BY CASE WHEN budget >= 3674000 THEN 'high' WHEN budget >= 988000 THEN 'mid' ELSE 'low' END, CASE WHEN location IN ('Berlin', 'Chiang Mai') THEN 'tier_1' ELSE 'other' END) SELECT budget_bucket, engineering_count FROM summary ORDER BY budget_bucket DESC;
